      SUBROUTINE TWISSCC     PRINTS BEAM OUTPUT IN COURANT-SNYDER PARAMETER NOTATIONC     (SOMETIMES ERRONEOUSLY CALLED "TWISS PARAMETERS")CC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM7C.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'IOUNIT.CIN'C -------------------------------------------------------------------      LOGICAL         UBIG, UNSEP      REAL            OUTPUT(10)CC     CUMULATIVE LENGTHC      ALONG = LC/UFLOOR(1)CC     ACCELERATOR NOTATIONC      IF (.NOT. RECENT) CALL BEAM      UBIG = UBEAM(1) .GT. 0.5 .AND. UBEAM(2) .GT. 0.5      IF (.NOT. SOFA .AND. .NOT. CPS) GO TO 20      IF (.NOT. CPR .AND. CPS) GO TO 20      DO 10 J = 1, 6      OUTPUT(J) = CEN(J)/UBEAM(J)   10 CONTINUE      IF (.NOT. LCPR .AND. .NOT. UBIG) THEN        WRITE (NOUT,1013) ALONG, XFLOOR(1),     1                    (OUTPUT(J), XBEAM(J), J = 1, 6) 1013   FORMAT (1H ,8X,F10.3,1X,A4,11X,6(F8.3,1X,A4),1X,2F9.3)      ELSE IF (.NOT. LCPR .AND. UBIG) THEN        WRITE (NOUT,1018) ALONG, XFLOOR(1),     1                    (OUTPUT(J), XBEAM(J), J = 1, 6) 1018   FORMAT (1H ,8X,F10.3,1X,A4,11X,6(F8.5,1X,A4),1X,2F9.3)      ELSE IF (LCPR .AND. .NOT. UBIG) THEN        WRITE (NOUT,1017) (OUTPUT(J), XBEAM(J), J = 1, 6) 1017   FORMAT (1H ,34X,6(F8.3,1X,A4),1X,2F9.3)      ELSE        WRITE (NOUT,1019) (OUTPUT(J), XBEAM(J), J = 1, 6) 1019   FORMAT (1H ,34X,6(F8.5,1X,A4),1X,2F9.3)      ENDIF      LCPR = .TRUE.C   20 UNSEP = SIT(1,3) .NE. 0.0      UNSEP = UNSEP .OR. SIT(1,4) .NE. 0.0      UNSEP = UNSEP .OR. SIT(2,3) .NE. 0.0      UNSEP = UNSEP .OR. SIT(2,4) .NE. 0.0      IF (WARN20 .AND. UNSEP) WRITE (NOUT,1012) 1012 FORMAT ('*** WARNING TRANSVERSE PLANES ARE NOT INDEPENDENT. ',     1        'TWISS PARAMETERS MAY NOT BE MEANINGFUL ***')C      EPSX = SQRT(SIT(1,1)*SIT(2,2) - SIT(1,2)**2)      EPSY = SQRT(SIT(3,3)*SIT(4,4) - SIT(3,4)**2)      OUTPUT(1) = PSIX/UNITO(12)      OUTPUT(2) = PSIY/UNITO(12)      OUTPUT(3) = SIT(1,1)*UBEAM(2)/(EPSX*UBEAM(1))      OUTPUT(4) = SIT(3,3)*UBEAM(4)/(EPSY*UBEAM(3))      OUTPUT(5) = - SIT(1,2)/EPSX      OUTPUT(6) = - SIT(3,4)/EPSY      OUTPUT(7) = ETA(1)/UBEAM(1)      OUTPUT(8) = ETA(3)/UBEAM(3)      OUTPUT(9) = ETA(2)/UBEAM(2)      OUTPUT(10) = ETA(4)/UBEAM(4)      IF (.NOT. LCPR) THEN        WRITE (NOUT,1025) ALONG, XFLOOR(1), (OUTPUT(J), J = 1, 10) 1025   FORMAT (1H ,8X,F10.3,1X,A4,8X,10F10.4)      ELSE        WRITE (NOUT,1026) (OUTPUT(J), J = 1, 10) 1026   FORMAT (1H ,31X,10F10.4)      ENDIF      IF (WARN20 .AND. UNSEP) WRITE (NOUT,1012)C      LCPR = .TRUE.      TDUN = .TRUE.      RETURN      END